mapper.select:
SELECT

FROM task_assignment
WHERE 1=1

    AND project_id = #{param.projectId}


    AND task_no LIKE CONCAT('%', #{param.taskNo}, '%')


    AND task_name LIKE CONCAT('%', #{param.taskName}, '%')


    AND task_type = #{param.taskType}


    AND task_status = #{param.taskStatus}


    AND assigned_person_id = #{param.responsiblePersonId}


    AND issuer_id = #{param.issuerId}


    AND reviewer_id = #{param.reviewerId}


    AND planned_start_date >= #{param.plannedStartDateStart}


    AND planned_end_date <= #{param.plannedEndDateEnd}

ORDER BY create_time DESC
